class DiscountStrategy:
    FIDELITY_THRESHOLD = 1000
    FIDELITY_DISCOUNT_RATE = 0.05
    BULK_QUANTITY_THRESHOLD = 20
    BULK_DISCOUNT_RATE = 0.1
    LARGE_ORDER_ITEM_THRESHOLD = 10
    LARGE_ORDER_DISCOUNT_RATE = 0.07

    def __init__(self, customer, cart, promotion=None):
        self.__customer = None
        self.__cart = None
        self.promotion = promotion
        self.__total = None
        self.set_customer(customer)
        self.set_cart(cart)

    def set_customer(self, customer):
        self.__customer = customer

    def get_customer(self):
        return self.__customer

    def set_cart(self, cart):
        self.__cart = cart

    def get_cart(self):
        return self.__cart

    @property
    def total(self):
        self.__total = self._calculate_total()
        return self.__total

    def _calculate_total(self):
        return sum(item['quantity'] * item['price'] for item in self.get_cart())

    def due(self):
        if self.promotion is None:
            return self.total
        discount = self.promotion(self)
        return self.total - discount

    @staticmethod
    def FidelityPromo(order):
        return order.total * 0.05 if order.get_customer()['fidelity'] >= 1000 else 0

    @staticmethod
    def BulkItemPromo(order):
        discount = 0
        for item in order.get_cart():
            if item['quantity'] >= 20:
                discount += item['quantity'] * item['price'] * 0.1
        return discount

    @staticmethod
    def LargeOrderPromo(order):
        return order.total * 0.07 if len({item['product'] for item in order.get_cart()}) >= 10 else 0
